def read_json(rel_path: str) -> dict:
    return json.loads((PACKAGE_DIR / rel_path).read_text(encoding="utf-8", errors="replace"))


def parse_dt(value: str) -> datetime:
    return datetime.fromisoformat(value.replace("Z", "+00:00").replace("+00:00", ""))


def inclusive_days(start_date: str, end_date: str) -> int:
    start = datetime.fromisoformat(start_date).date()
    end = datetime.fromisoformat(end_date).date()
    return (end - start).days + 1


def ratio(numerator: float, denominator: float) -> float:
    return round(numerator / denominator, 3) if denominator else 0.0


def pct_difference(a: float, b: float) -> float:
    return round(abs(a - b) / ((a + b) / 2.0) * 100.0, 3)


def overlap_hours(start_a: datetime, end_a: datetime, start_b: datetime, end_b: datetime) -> float:
    overlap = min(end_a, end_b) - max(start_a, start_b)
    return round(max(0.0, overlap.total_seconds() / 3600.0), 1)


def longest_positive_run(values: list[float]) -> int:
    best = 0
    current = 0
    for value in values:
        if value > 0:
            current += 1
            best = max(best, current)
        else:
            current = 0
    return best


def alert_metrics(event_start_date: str) -> dict:
    catalog = read_json("data/event_catalogs/event_catalogs_001_GDACS_event_list_GeoJSON_API.json")
    features = [
        feature
        for feature in catalog.get("features", [])
        if feature.get("properties", {}).get("eventtype") == "FL"
        and feature.get("properties", {}).get("iso3") in {"DEU", "BEL"}
    ]
    features.sort(key=lambda feature: feature["properties"]["fromdate"])
    event_start = datetime.fromisoformat(f"{event_start_date}T00:00:00")
    starts = [parse_dt(feature["properties"]["fromdate"]) for feature in features]
    ends = [parse_dt(feature["properties"]["todate"]) for feature in features]

    lags = {}
    windows = {}
    for feature, start, end in zip(features, starts, ends):
        country = feature["properties"]["country"]
        lags[country] = round((start - event_start).total_seconds() / 3600.0, 1)
        windows[country] = {
            "start": start.isoformat(timespec="minutes"),
            "end": end.isoformat(timespec="minutes"),
        }

    return {
        "alert_windows": windows,
        "alert_lag_hours": lags,
        "alert_onset_gap_hours": round((max(starts) - min(starts)).total_seconds() / 3600.0, 1),
        "alert_combined_window_hours": round((max(ends) - min(starts)).total_seconds() / 3600.0, 1),
        "alert_overlap_hours": overlap_hours(starts[0], ends[0], starts[1], ends[1]),
    }


def rainfall_metrics() -> dict:
    era5 = read_json("data/physical_hazard/physical_hazard_005_ERA5-Land_hourly_aggregate_stats.json")["stats"]
    gpm = read_json("data/physical_hazard/physical_hazard_007_GPM_IMERG_V07_event_accumulated_precipitation.json")["stats"]
    open_meteo = read_json("data/physical_hazard/physical_hazard_003_Open-Meteo_historical_weather_point_API.json")

    hourly_times = [datetime.fromisoformat(value) for value in open_meteo["hourly"]["time"]]
    hourly_precip = [float(value) for value in open_meteo["hourly"]["precipitation"]]
    wet_indices = [idx for idx, value in enumerate(hourly_precip) if value > 0]
    wet_span = (hourly_times[wet_indices[-1]] - hourly_times[wet_indices[0]]).total_seconds() / 3600.0
    peak = max(hourly_precip)
    peak_index = hourly_precip.index(peak)
    local_total = sum(hourly_precip)
    satellite_max = float(gpm["gpm_event_precip_mm_max"])
    satellite_mean = float(gpm["gpm_event_precip_mm_mean"])
    reanalysis_max = float(era5["precipitation_sum_mm_max"])
    reanalysis_mean = float(era5["precipitation_sum_mm_mean"])

    return {
        "satellite_max_mm": round(satellite_max, 3),
        "satellite_mean_mm": round(satellite_mean, 3),
        "reanalysis_max_mm": round(reanalysis_max, 3),
        "reanalysis_mean_mm": round(reanalysis_mean, 3),
        "satellite_max_mean_ratio": ratio(satellite_max, satellite_mean),
        "reanalysis_max_mean_ratio": ratio(reanalysis_max, reanalysis_mean),
        "gridded_max_difference_pct": pct_difference(satellite_max, reanalysis_max),
        "local_total_mm": round(local_total, 3),
        "local_peak_hour_mm": round(peak, 3),
        "local_peak_hour_time": hourly_times[peak_index].isoformat(timespec="minutes"),
        "local_peak_share": ratio(peak, local_total),
        "local_wet_span_hours": round(wet_span, 1),
        "local_longest_wet_run_hours": longest_positive_run(hourly_precip),
        "local_total_to_satellite_max_ratio": ratio(local_total, satellite_max),
    }


def proof_blocks(values: dict) -> list[dict]:
    event_hours = values["event_window_hours"]
    combined = values["alert_combined_window_hours"]
    overlap = values["alert_overlap_hours"]
    gap = values["alert_onset_gap_hours"]
    germany_lag = values["alert_lag_hours"]["Germany"]
    belgium_lag = values["alert_lag_hours"]["Belgium"]

    return [
        {
            "block_id": "event_window_and_alert_lags",
            "formula": ["inclusive_days*24", "alert_start-event_start", "lag/event_window_hours"],
            "computed_values": {
                "event_window_hours": event_hours,
                "Germany_lag_hours": germany_lag,
                "Belgium_lag_hours": belgium_lag,
                "Germany_lag_ratio": ratio(germany_lag, event_hours),
                "Belgium_lag_ratio": ratio(belgium_lag, event_hours),
            },
            "result": "lagged_alert_timing_pass",
        },
        {
            "block_id": "cross_border_alert_timing",
            "formula": [
                "max(alert_end)-min(alert_start)",
                "later_alert_start-earlier_alert_start",
                "alert_overlap_hours",
                "combined_window/event_window_hours",
                "overlap/combined_window",
                "onset_gap/event_window_hours",
            ],
            "computed_values": {
                "combined_alert_window_hours": combined,
                "alert_onset_gap_hours": gap,
                "alert_overlap_hours": overlap,
                "combined_window_ratio": ratio(combined, event_hours),
                "overlap_combined_ratio": ratio(overlap, combined),
                "onset_gap_ratio": ratio(gap, event_hours),
            },
            "result": "cross_border_timing_pass",
        },
        {
            "block_id": "gridded_rainfall_consistency",
            "formula": [
                "satellite_max/satellite_mean",
                "reanalysis_max/reanalysis_mean",
                "abs(satellite_max-reanalysis_max)/mean(satellite_max,reanalysis_max)*100",
            ],
            "computed_values": {
                "satellite_max_mean_ratio": values["satellite_max_mean_ratio"],
                "reanalysis_max_mean_ratio": values["reanalysis_max_mean_ratio"],
                "gridded_max_difference_pct": values["gridded_max_difference_pct"],
            },
            "result": "gridded_rainfall_consistency_pass",
        },
        {
            "block_id": "local_hourly_rain_spike_test",
            "formula": [
                "local_peak_hour/local_total",
                "longest_wet_run/event_window_hours",
                "wet_span/event_window_hours",
                "local_total/satellite_max",
            ],
            "computed_values": {
                "local_peak_share": values["local_peak_share"],
                "longest_wet_run_ratio": ratio(values["local_longest_wet_run_hours"], event_hours),
                "wet_span_ratio": ratio(values["local_wet_span_hours"], event_hours),
                "local_total_to_satellite_max_ratio": values["local_total_to_satellite_max_ratio"],
            },
            "result": "single_hour_spike_fails",
        },
    ]


