def main() -> None:
    event = read_json("metadata/event.json")
    anchor = read_json("data/event_reports/event_reports_003_Locked_event_anchor_July_2021_Western_Europe_floods.json")
    window = anchor["temporal_window"]
    alerts = alert_metrics(window["start_date"])
    rain = rainfall_metrics()

    event_days = inclusive_days(window["start_date"], window["end_date"])
    event_hours = event_days * 24
    key_values = {
        "event_name": event["event_name"],
        "hazard_family": event["hazard_family"],
        "event_window_start": window["start_date"],
        "event_window_end": window["end_date"],
        "event_window_days": event_days,
        "event_window_hours": event_hours,
        **alerts,
        **rain,
    }
    key_values.update({
        "Germany_lag_ratio": ratio(key_values["alert_lag_hours"]["Germany"], event_hours),
        "Belgium_lag_ratio": ratio(key_values["alert_lag_hours"]["Belgium"], event_hours),
        "combined_window_ratio": ratio(key_values["alert_combined_window_hours"], event_hours),
        "overlap_combined_ratio": ratio(key_values["alert_overlap_hours"], key_values["alert_combined_window_hours"]),
        "onset_gap_ratio": ratio(key_values["alert_onset_gap_hours"], event_hours),
        "longest_wet_run_ratio": ratio(key_values["local_longest_wet_run_hours"], event_hours),
        "wet_span_ratio": ratio(key_values["local_wet_span_hours"], event_hours),
    })

    rejected_alternatives = [
        "single_local_hourly_spike",
        "rainfall_total_without_lag",
        "single_country_alert_sequence",
    ]
    final_label = "multiday_rainfall_to_river_routing_lag_consistent"
    blocks = proof_blocks(key_values)

    gt = {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "short_answer",
        "target_family": TARGET_FAMILY,
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "primary_gt": {
            "target_family": TARGET_FAMILY,
            "proof_blocks": blocks,
            "rejected_alternatives": rejected_alternatives,
            "final_label": final_label,
        },
        "key_values": key_values,
        "tolerances": {"hours": 0.1, "ratios": 0.005, "percent": 0.01},
        "proof_blocks": blocks,
        "decision_rule": {
            "final_label": final_label,
            "conditions": [
                "event_window_hours == 120",
                "Germany_lag_hours == 25.0 and Belgium_lag_hours == 49.0",
                "alert_onset_gap_hours == 24.0 and alert_combined_window_hours == 72.0",
                "gridded_max_difference_pct <= 0.05",
                "local_peak_share < 0.10 and wet_span_ratio >= 0.50",
            ],
        },
        "rubric": rubric(),
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_package": f"event_packages/standard_event_packages/packages/{EVENT_ID}",
            "source_files": SOURCE_FILES,
        },
    }
    apply_deepened_task_frame(gt)
    (TASK_DIR / "computed_gt.json").write_text(json.dumps(gt, indent=2, ensure_ascii=True) + "\n", encoding="utf-8")


if __name__ == "__main__":
